import React, { useState } from "react";
import styled from "styled-components";
import { doc, deleteDoc, updateDoc, increment, getDoc } from "firebase/firestore";
import { db } from "../firebase";

type Props = {
    id: string;           // id транзакції
    productId: string;    // товар який продавали
    quantity: number;     // скільки продали
};

export const DeleteTransactionButton: React.FC<Props> = ({ id, productId, quantity }) => {
    const [loading, setLoading] = useState(false);

    const handleDelete = async () => {
        if (!window.confirm("Видалити цей продаж?")) return;

        setLoading(true);
        try {
            // 1. Повертаємо товар на склад
            const productRef = doc(db, "products", productId);
            await updateDoc(productRef, {
                stock: increment(quantity),  // повертаємо кількість
                sold: increment(-quantity),  // забираємо з sold
            });

            // 2. Видаляємо транзакцію
            await deleteDoc(doc(db, "transactions", id));

            alert("Продаж видалено");
            window.location.reload();
        } catch (err: any) {
            alert("Помилка: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Button disabled={loading} onClick={handleDelete}>
            ❌ Видалити
        </Button>
    );
};

const Button = styled.button`
    padding: 4px 10px;
    background: #ef4444;
    color: white;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-size: 14px;

    &:hover {
        opacity: 0.85;
    }
`;
