import React, {useState, useEffect} from "react";
import styled from "styled-components";
import {
    doc,
    getDoc,
    setDoc,
    collection,
    getDocs,
    deleteDoc,
} from "firebase/firestore";
import {db} from "../firebase";
import {useFirestoreCollection} from "../hooks/useFirestoreCollection";
import {CATEGORIES} from "../types/categories";
import {EditProductModal} from "../components/EditProductModal";
import {DeleteTransactionButton} from "../components/DeleteTransactionButton";

type Product = {
    id?: string;
    name: string;
    buyPrice: number;
    sellPrice: number;
    stock: number;
    sold?: number;
    used?: number;
    photo?: string;
    category: string;
};


type Barber = {
    id?: string;
    name: string
};

export const AdminPage = () => {

    const {data: barbers} = useFirestoreCollection<Barber>("barbers");
    const {data: products, addItem} =
        useFirestoreCollection<Product>("products");

    const [balance, setBalance] = useState<number>(0);
    const [editingProduct, setEditingProduct] = useState<Product | null>(null);
    const [transactions, setTransactions] = useState<any[]>([]);

    // ---------------- BALANCE LOAD ----------------
    useEffect(() => {
        const loadBalance = async () => {
            const ref = doc(db, "settings", "balance");
            const snap = await getDoc(ref);
            if (snap.exists()) setBalance(snap.data().value || 0);
        };
        loadBalance();
    }, []);

    useEffect(() => {
        const load = async () => {
            const snap = await getDocs(collection(db, "transactions"));
            const arr: any[] = [];
            snap.forEach((d) => {
                arr.push({id: d.id, ...d.data()});
            });
            setTransactions(arr);
        };
        load();
    }, []);

    const saveBalance = async (v: number) => {
        await setDoc(doc(db, "settings", "balance"), {value: v});
        setBalance(v);
    };

    // ---------------- FORM STATE ----------------
    const [name, setName] = useState("");
    const [buyPrice, setBuyPrice] = useState("");
    const [sellPrice, setSellPrice] = useState("");
    const [stock, setStock] = useState("");
    const [category, setCategory] = useState("");
    const [photo, setPhoto] = useState<string>("");

    const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onloadend = () => setPhoto(reader.result as string);
        reader.readAsDataURL(file);
    };

    const handleAdd = async () => {
        const bp = Number(buyPrice);
        const sp = Number(sellPrice);
        const st = Number(stock);

        if (!name.trim() || !category || bp <= 0 || sp <= 0 || st <= 0) {
            alert("Заповніть всі поля!");
            return;
        }

        await addItem({
            name,
            buyPrice: bp,
            sellPrice: sp,
            stock: st,
            sold: 0,
            used: 0,
            photo: photo || "",
            category,
        });

        setName("");
        setBuyPrice("");
        setSellPrice("");
        setStock("");
        setCategory("");
        setPhoto("");
    };

    // ---------------- CALCULATE TOTALS ----------------
    let totalSoldBuy = 0;
    let totalSoldSell = 0;

    products.forEach((p) => {
        const sold = p.sold || 0;
        totalSoldBuy += sold * p.buyPrice;
        totalSoldSell += sold * p.sellPrice;
    });

    const profit = totalSoldSell - totalSoldBuy;

    useEffect(() => {
        saveBalance(profit);
    }, [profit]);

    // ---------------- DROP DATABASE ----------------
    const handleDropDatabase = async () => {
        const pass = prompt("Введіть пароль для видалення бази:");

        if (pass !== "321") {
            alert("❌ Невірний пароль");
            return;
        }

        if (!window.confirm("⚠ Видалити ВСІ дані?")) return;

        try {
            const deleteCollection = async (col: string) => {
                const colRef = collection(db, col);
                const snap = await getDocs(colRef);
                for (const item of snap.docs) {
                    await deleteDoc(item.ref);
                }
            };

            await deleteCollection("products");
            await deleteCollection("barbers");
            await deleteCollection("transactions");

            await setDoc(doc(db, "settings", "balance"), {value: 0});

            alert("🗑 Базу очищено!");
            window.location.reload();
        } catch (err) {
            console.error(err);
            alert("Помилка очищення.");
        }
    };

    const openEditor = (p: Product) => setEditingProduct(p);
    const closeEditor = () => setEditingProduct(null);

    return (
        <Page>
            <Card>
                <Title>Адмінка товарів</Title>

                {/* ---------- FORM ---------- */}
                <FormRow>
                    <Input
                        placeholder="Назва"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                    />

                    <Select value={category} onChange={(e) => setCategory(e.target.value)}>
                        <option value="">Категорія</option>
                        {CATEGORIES.map((c) => (
                            <option key={c} value={c}>
                                {c}
                            </option>
                        ))}
                    </Select>

                    <Input
                        type="number"
                        placeholder="Вхідна"
                        value={buyPrice}
                        onChange={(e) => setBuyPrice(e.target.value)}
                    />

                    <Input
                        type="number"
                        placeholder="Продажна"
                        value={sellPrice}
                        onChange={(e) => setSellPrice(e.target.value)}
                    />

                    <Input
                        type="number"
                        placeholder="К-сть"
                        value={stock}
                        onChange={(e) => setStock(e.target.value)}
                    />

                    <FileUploadContainer>
                        <FileLabel htmlFor="photoInput">📷 Фото</FileLabel>
                        <HiddenFileInput
                            id="photoInput"
                            type="file"
                            accept="image/*"
                            onChange={handlePhotoUpload}
                        />
                        <FileName>{photo ? "Фото вибрано" : "Файл не вибрано"}</FileName>
                    </FileUploadContainer>
                </FormRow>

                <AddButton onClick={handleAdd}>Додати товар</AddButton>

                {/* ---------- TABLE ---------- */}
                <h3 style={{marginTop: 30}}>Товари</h3>

                <TableWrapper>
                    <Table>
                        <thead>
                        <tr>
                            <th>Фото</th>
                            <th>Назва</th>
                            <th>Категорія</th>
                            <th>Вхідна</th>
                            <th>Продаж</th>
                            <th>Залишок</th>
                            <th>Продано</th>
                            <th>Сума прод.</th>
                            <th>Прибуток</th>
                            <th>Дії</th>
                        </tr>
                        </thead>

                        <tbody>
                        {products.map((p) => {
                            const sold = p.sold || 0;
                            const soldAmount = sold * p.sellPrice;
                            const soldBuyCost = sold * p.buyPrice;
                            const profitRow = soldAmount - soldBuyCost;

                            return (
                                <tr key={p.id}>
                                    <td>
                                        {p.photo && (
                                            <img
                                                src={p.photo}
                                                alt={p.name}
                                                style={{
                                                    width: 50,
                                                    height: 50,
                                                    borderRadius: 6,
                                                    objectFit: "cover",
                                                }}
                                            />
                                        )}
                                    </td>

                                    <td>{p.name}</td>
                                    <td>{p.category}</td>
                                    <td>{p.buyPrice}</td>
                                    <td>{p.sellPrice}</td>
                                    <td>{p.stock}</td>
                                    <td>{sold}</td>
                                    <td>{soldAmount} грн</td>
                                    <td style={{color: "#22c55e", fontWeight: 600}}>
                                        {profitRow}
                                    </td>

                                    <td>
                                        <EditButton onClick={() => openEditor(p)}>✏️</EditButton>
                                    </td>
                                </tr>
                            );
                        })}
                        </tbody>
                    </Table>
                </TableWrapper>

                <AddButton style={{background: "#ef4444"}} onClick={handleDropDatabase}>
                    🗑 Дропнути базу (321)
                </AddButton>

                {editingProduct && (
                    <EditProductModal product={editingProduct} onClose={closeEditor}/>
                )}

                <h3>Продажі</h3>

                {transactions
                    .filter(t => t.type === "sale")
                    .sort((a, b) => b.timestamp - a.timestamp)
                    .map((t) => {
                        const product = products.find(p => p.id === t.productId)?.name ?? "Товар";
                        const barber = barbers.find(b => b.id === t.barberId)?.name ?? "Барбер";

                        return (
                            <div
                                key={t.id}
                                style={{
                                    padding: "10px 0",
                                    borderBottom: "1px solid #eee",
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center"
                                }}
                            >
                                <div>
                                    <b>{product}</b> — {t.quantity} шт — {t.totalSell} грн
                                    <br/>
                                    <small>{barber}</small>
                                </div>

                                <DeleteTransactionButton
                                    id={t.id}
                                    productId={t.productId}
                                    quantity={t.quantity}
                                />
                            </div>
                        );
                    })}
            </Card>
        </Page>
    );
};

/* =================== STYLES =================== */

const Page = styled.div`
    width: 100%;
    padding: 20px;
    background: #f6f8fa;
    display: flex;
    justify-content: center;
    box-sizing: border-box;
`;

const Card = styled.div`
    width: 100%;
    background: white;
    padding: 20px;
    border-radius: 14px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
    box-sizing: border-box;
`;

const Title = styled.h2`
    margin-bottom: 20px;
    font-size: 1.8rem;
`;

const FormRow = styled.div`
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
    gap: 12px;
    margin-bottom: 16px;
    align-items: center;

    @media (max-width: 900px) {
        grid-template-columns: 1fr 1fr 1fr;
    }
    @media (max-width: 600px) {
        grid-template-columns: 1fr;
    }
`;

const Input = styled.input`
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid #bbb;
    font-size: 1rem;

    &:focus {
        border-color: #4f8cff;
        outline: none;
    }
`;

const Select = styled.select`
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid #bbb;
    font-size: 1rem;
`;

const FileUploadContainer = styled.div`
    display: flex;
    flex-direction: column;
    gap: 4px;
`;

const FileLabel = styled.label`
    background: #3b82f6;
    color: white;
    padding: 10px 14px;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
`;

const HiddenFileInput = styled.input`
    display: none;
`;

const FileName = styled.div`
    font-size: 0.85rem;
    color: #555;
`;

const AddButton = styled.button`
    background: #4caf50;
    color: white;
    border: none;
    padding: 12px 20px;
    border-radius: 10px;
    margin-top: 10px;
    cursor: pointer;
    font-weight: 600;

    &:hover {
        opacity: 0.9;
    }
`;

const TableWrapper = styled.div`
    overflow-x: auto;
`;

const Table = styled.table`
    width: 100%;
    border-collapse: collapse;

    th,
    td {
        padding: 10px;
        border-bottom: 1px solid #e2e8f0;
        text-align: left;
    }

    th {
        background: #f8fafc;
        font-weight: 600;
    }
`;

const EditButton = styled.button`
    background: #3b82f6;
    color: white;
    border: none;
    padding: 6px 10px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 14px;

    &:hover {
        opacity: 0.9;
    }
`;
