import { useEffect, useState, useCallback } from "react";
import {
    collection,
    addDoc,
    deleteDoc,
    doc,
    getDocs,
    updateDoc,
    DocumentData,
} from "firebase/firestore";
import { db } from "../firebase";

export const useFirestoreCollection = <T extends { id?: string }>(path: string) => {
    const [data, setData] = useState<T[]>([]);
    const [loading, setLoading] = useState(true);

    const reload = useCallback(async () => {
        setLoading(true);
        try {
            const snap = await getDocs(collection(db, path));
            setData(snap.docs.map((d) => ({ id: d.id, ...d.data() } as T)));
        } finally {
            setLoading(false);
        }
    }, [path]);

    useEffect(() => {
        reload();
    }, [reload]);

    const addItem = async (item: Omit<T, "id">) => {
        await addDoc(collection(db, path), item as DocumentData);
        await reload();
    };

    const updateItem = async (id: string, item: Partial<T>) => {
        await updateDoc(doc(db, path, id), item as DocumentData);
        await reload();
    };

    const deleteItem = async (id: string) => {
        await deleteDoc(doc(db, path, id));
        await reload();
    };

    return { data, loading, addItem, updateItem, deleteItem, reload };
};
