import React, { useState, useEffect } from "react";
import styled from "styled-components";
import {
    collection,
    doc,
    updateDoc,
    addDoc,
    increment,
    getDoc,
    getDocs,
} from "firebase/firestore";
import { db } from "../firebase";
import { useFirestoreCollection } from "../hooks/useFirestoreCollection";
import { useNavigate } from "react-router-dom";
import { CATEGORIES } from "../types/categories";
import { DeleteTransactionButton } from "../components/DeleteTransactionButton";

type Product = {
    id?: string;
    name: string;
    buyPrice: number;
    sellPrice: number;
    stock: number;
    sold?: number;
    used?: number;
    photo?: string;
    category: string;
};

type Barber = { id?: string; name: string };

export const SalesPage = () => {
    const { data: products } = useFirestoreCollection<Product>("products");
    const { data: barbers } = useFirestoreCollection<Barber>("barbers");

    const [barberId, setBarberId] = useState("");
    const [category, setCategory] = useState("");
    const [productId, setProductId] = useState("");
    const [quantity, setQuantity] = useState(1);
    const [sales, setSales] = useState<any[]>([]);
    const [openBarber, setOpenBarber] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    const navigate = useNavigate();

    // FILTERED PRODUCTS BY CATEGORY
    const filteredProducts = category
        ? products.filter((p) => p.category === category)
        : [];

    // Load sales WITH ID
    useEffect(() => {
        const loadSales = async () => {
            const snap = await getDocs(collection(db, "transactions"));
            const arr: any[] = [];

            snap.forEach((d) => {
                const data = d.data();
                if (data.type === "sale") {
                    arr.push({ id: d.id, ...data });
                }
            });

            setSales(arr);
        };

        loadSales();
    }, []);

    // GROUP BY BARBER
    const grouped = sales.reduce((acc: any, t: any) => {
        if (!acc[t.barberId]) acc[t.barberId] = [];
        acc[t.barberId].push(t);
        return acc;
    }, {});

    /* ==============================================================
       HANDLE TRANSACTION
    ============================================================== */
    const handleTransaction = async (type: "sale" | "usage") => {
        if (!barberId || !productId || quantity <= 0) {
            alert("Заповніть всі поля");
            return;
        }

        setLoading(true);
        try {
            const ref = doc(db, "products", productId);
            const snap = await getDoc(ref);
            const product = snap.data() as Product;

            if (product.stock < quantity) {
                throw new Error("Недостатня кількість товару");
            }

            const totalBuy = product.buyPrice * quantity;
            const totalSell = product.sellPrice * quantity;

            // Update product stock
            await updateDoc(ref, {
                stock: product.stock - quantity,
                sold: type === "sale" ? increment(quantity) : increment(0),
                used: type === "usage" ? increment(quantity) : increment(0),
            });

            // Add transaction
            await addDoc(collection(db, "transactions"), {
                type,
                productId,
                barberId,
                quantity,
                totalBuy,
                totalSell,
                timestamp: Date.now(),
            });

            // Redirect logic
            if (type === "sale") {
                navigate("/payment", {
                    state: {
                        barberId,
                        productId,
                        quantity,
                        totalSell,
                        productName: product.name,
                    },
                });
            } else {
                navigate("/");
            }
        } catch (err: any) {
            alert(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Wrapper>
            <Card>
                <Title>Продаж / Списання</Title>

                {/* BARBER */}
                <Label>Барбер</Label>
                <InputWrapper>
                    <Select value={barberId} onChange={(e) => setBarberId(e.target.value)}>
                        <option value="">Виберіть барбера</option>
                        {barbers.map((b) => (
                            <option key={b.id} value={b.id}>
                                {b.name}
                            </option>
                        ))}
                    </Select>
                </InputWrapper>

                {/* CATEGORY */}
                <Label>Категорія</Label>
                <InputWrapper>
                    <Select
                        value={category}
                        onChange={(e) => {
                            setCategory(e.target.value);
                            setProductId("");
                        }}
                    >
                        <option value="">Виберіть категорію</option>
                        {CATEGORIES.map((c) => (
                            <option key={c} value={c}>
                                {c}
                            </option>
                        ))}
                    </Select>
                </InputWrapper>

                {/* PRODUCT */}
                <Label>Товар</Label>
                <InputWrapper>
                    <Select
                        value={productId}
                        onChange={(e) => setProductId(e.target.value)}
                        disabled={!category}
                    >
                        <option value="">
                            {category ? "Виберіть товар" : "Спочатку виберіть категорію"}
                        </option>

                        {filteredProducts.map((p) => (
                            <option key={p.id} value={p.id}>
                                {p.name} — {p.sellPrice} грн
                            </option>
                        ))}
                    </Select>
                </InputWrapper>

                {/* QUANTITY */}
                <Label>Кількість</Label>
                <InputWrapper>
                    <Input
                        type="number"
                        min="1"
                        value={quantity}
                        onChange={(e) => setQuantity(Number(e.target.value))}
                    />
                </InputWrapper>

                <Buttons>
                    <GreenButton disabled={loading} onClick={() => handleTransaction("sale")}>
                        💸 Продати
                    </GreenButton>
                    <RedButton disabled={loading} onClick={() => handleTransaction("usage")}>
                        🧴 Списати
                    </RedButton>
                </Buttons>
            </Card>

            {/* ================= BARBER SUMMARY ================ */}
            <StatsCard>
                <SubTitle>Підсумки по барберах</SubTitle>

                {Object.keys(grouped).length === 0 ? (
                    <Empty>Немає даних</Empty>
                ) : (
                    Object.keys(grouped).map((barberId) => {
                        const barber =
                            barbers.find((b) => b.id === barberId)?.name || "Барбер";

                        const totalQty = grouped[barberId].reduce(
                            (s: number, x: any) => s + x.quantity,
                            0
                        );
                        const totalSum = grouped[barberId].reduce(
                            (s: number, x: any) => s + x.totalSell,
                            0
                        );

                        const isOpen = openBarber === barberId;

                        return (
                            <div key={barberId}>
                                <AccordionHeader
                                    onClick={() =>
                                        setOpenBarber(isOpen ? null : barberId)
                                    }
                                >
                                    <b>{barber}</b>
                                    <span>{totalQty} шт</span>
                                    <span>{totalSum} грн</span>
                                    <Chevron>{isOpen ? "▲" : "▼"}</Chevron>
                                </AccordionHeader>

                                {isOpen && (
                                    <AccordionBody>
                                        {grouped[barberId].map((t: any, i: number) => {
                                            const product = products.find(
                                                (p) => p.id === t.productId
                                            )?.name;

                                            const date = new Date(
                                                t.timestamp
                                            ).toLocaleDateString("uk-UA");
                                            const time = new Date(
                                                t.timestamp
                                            ).toLocaleTimeString("uk-UA", {
                                                hour: "2-digit",
                                                minute: "2-digit",
                                            });

                                            return (
                                                <DetailRow key={i}>
                                                    <div>{date} — {time}</div>
                                                    <div>{product}</div>
                                                    <div>{t.quantity} шт</div>
                                                    <div>{t.totalSell} грн</div>
                                                </DetailRow>
                                            );
                                        })}
                                    </AccordionBody>
                                )}
                            </div>
                        );
                    })
                )}
            </StatsCard>
        </Wrapper>
    );
};

