import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { collection, getDocs, doc, getDoc, setDoc } from "firebase/firestore";
import { db } from "../firebase";

export const StatsPage = () => {
    const [products, setProducts] = useState<any[]>([]);
    const [barbers, setBarbers] = useState<any[]>([]);
    const [transactions, setTransactions] = useState<any[]>([]);
    const [cashout, setCashout] = useState(0);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        const prodSnap = await getDocs(collection(db, "products"));
        const barbSnap = await getDocs(collection(db, "barbers"));
        const tranSnap = await getDocs(collection(db, "transactions"));
        const cashSnap = await getDoc(doc(db, "settings", "cashout"));

        setProducts(prodSnap.docs.map(d => ({ id: d.id, ...d.data() })));
        setBarbers(barbSnap.docs.map(d => ({ id: d.id, ...d.data() })));
        setTransactions(tranSnap.docs.map(d => ({ id: d.id, ...d.data() })));

        if (cashSnap.exists()) setCashout(cashSnap.data().value || 0);
    };

    // ---------------- GLOBAL STATS ----------------

    const moneyInStockBuy = products.reduce((s, p) => s + p.stock * p.buyPrice, 0);
    const moneyInStockSell = products.reduce((s, p) => s + p.stock * p.sellPrice, 0);

    const soldTransactions = transactions.filter(t => t.type === "sale");

    const totalSoldSum = soldTransactions.reduce((s, t) => s + t.totalSell, 0);
    const totalSoldAfterCashout = totalSoldSum - cashout;

    // group by barber
    const grouped = soldTransactions.reduce((acc: any, t: any) => {
        if (!acc[t.barberId]) acc[t.barberId] = [];
        acc[t.barberId].push(t);
        return acc;
    }, {});

    const applyCashout = async (value: number) => {
        const newValue = cashout + value;
        await setDoc(doc(db, "settings", "cashout"), { value: newValue });
        setCashout(newValue);
        alert("Інкасація виконана!");
    };

    return (
        <Wrapper>
            <Card>

                <Title>Статистика</Title>

                {/* ---------------- GLOBAL STATS BLOCK ---------------- */}
                <StatsGrid>

                    <StatCard>
                        <Label>Грошей у товарі (закупка)</Label>
                        <Value>{moneyInStockBuy} грн</Value>
                    </StatCard>

                    <StatCard>
                        <Label>Грошей у товарі (продаж)</Label>
                        <Value>{moneyInStockSell} грн</Value>
                    </StatCard>

                    <StatCard>
                        <Label>Продано на суму</Label>
                        <Value>{totalSoldAfterCashout} грн</Value>

                        <CashoutInfo>Інкасовано: {cashout} грн</CashoutInfo>

                        <IncassoButton
                            onClick={() => {
                                const v = Number(prompt("Сума інкасації:"));
                                if (!v) return;
                                applyCashout(v);
                            }}
                        >
                            Інкасація
                        </IncassoButton>
                    </StatCard>

                    <StatCard>
                        <Label>Продаж по барберам</Label>

                        {barbers.map(b => {
                            const list = grouped[b.id] || [];
                            const sum = list.reduce((s:any, t:any) => s + t.totalSell, 0);

                            return (
                                <BarberRow key={b.id}>
                                    {b.name}: <strong>{sum} грн</strong>
                                </BarberRow>
                            );
                        })}
                    </StatCard>

                </StatsGrid>

                <Divider />

                {/* ---------------- YOUR OLD DETAIL SECTION (UNCHANGED) ---------------- */}

                <h3>Деталізація по барберам</h3>

                {barbers.map(b => {
                    const list = grouped[b.id] || [];

                    return (
                        <div key={b.id} style={{ marginTop: 20 }}>
                            <h4>{b.name}</h4>

                            {list.length === 0 ? (
                                <div style={{ opacity: 0.6 }}>Немає продажів</div>
                            ) : (
                                <DetailTable>
                                    <thead>
                                    <tr>
                                        <th>Дата</th>
                                        <th>Товар</th>
                                        <th>Кількість</th>
                                        <th>Сума</th>
                                    </tr>
                                    </thead>

                                    <tbody>
                                    {list.map((t:any) => {
                                        const date = new Date(t.timestamp).toLocaleString("uk-UA");
                                        const product = products.find(p => p.id === t.productId)?.name;

                                        return (
                                            <tr key={t.id}>
                                                <td>{date}</td>
                                                <td>{product}</td>
                                                <td>{t.quantity}</td>
                                                <td>{t.totalSell} грн</td>
                                            </tr>
                                        );
                                    })}
                                    </tbody>
                                </DetailTable>
                            )}
                        </div>
                    );
                })}

            </Card>
        </Wrapper>
    );
};


/* ===================== STYLES ===================== */

const Wrapper = styled.div`
    padding: 20px;
    display: flex;
    justify-content: center;
`;

const Card = styled.div`
    width: 100%;
    max-width: 900px;
    background: white;
    padding: 20px;
    border-radius: 12px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
`;

const Title = styled.h2`
    margin-bottom: 20px;
`;

const StatsGrid = styled.div`
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
`;

const StatCard = styled.div`
    background: #f1f5f9;
    padding: 16px;
    border-radius: 10px;
`;

const Label = styled.div`
    opacity: 0.7;
    margin-bottom: 6px;
`;

const Value = styled.div`
    font-weight: 700;
    font-size: 1.3rem;
`;

const CashoutInfo = styled.div`
    margin-top: 6px;
    font-size: 0.9rem;
    opacity: 0.6;
`;

const BarberRow = styled.div`
    margin-top: 4px;
`;

const IncassoButton = styled.button`
    margin-top: 10px;
    background: #ef4444;
    color: white;
    padding: 8px 12px;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
`;

const Divider = styled.div`
    height: 1px;
    background: #ddd;
    margin: 25px 0;
`;

const DetailTable = styled.table`
    width: 100%;
    border-collapse: collapse;

    th, td {
        border-bottom: 1px solid #eee;
        padding: 8px 6px;
    }

    th {
        background: #f8fafc;
    }
`;
